require __DIR__.'/includes/bootstrap.php';if(current_user())redirect('account.php');$error='';$username='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT id,username,email,password_hash,role FROM users WHERE username=:u LIMIT 1');$s->execute(['u'=>$username]);$u=$s->fetch();if($u&&password_verify($password,$u['password_hash'])){if(password_needs_rehash($u['password_hash'],defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT)){$newHash=password_hash($password,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT);$pdo->prepare('UPDATE users SET password_hash=:p WHERE id=:id')->execute(['p'=>$newHash,'id'=>$u['id']]);}session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'username'=>$u['username'],'email'=>$u['email'],'role'=>$u['role']];flash('Connexion réussie.','success');redirect('account.php');}else{$error='Pseudo ou mot de passe incorrect.';}}
$pageTitle='Connexion';require __DIR__.'/includes/header.php';?>
<section class="panel"><h1>Connexion</h1><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="username">Pseudo</label><input id="username" name="username" maxlength="15" required value="<?=e($username)?>" autocomplete="username"></div><div class="field"><label for="password">Mot de passe</label><input id="password" type="password" name="password" required autocomplete="current-password"></div><button class="btn" type="submit">Se connecter</button></form><p>Pas encore de compte ? <a href="<?=e(url('register.php'))?>">Créer un compte</a></p></section>
